package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class InterestCalculator {
    public long monthlyInterest(long balanceCents, long annualRatePercent) {
        BigDecimal balance = BigDecimal.valueOf(balanceCents, 2);
        BigDecimal rate = BigDecimal.valueOf(annualRatePercent);
        BigDecimal interest = balance.multiply(rate)
                .divide(BigDecimal.valueOf(1200), 2, RoundingMode.HALF_UP);
        return interest.movePointRight(2).longValue();
    }
}

