package com.rustybank.legacy;

import java.math.BigDecimal;

public class MoneyUtil {
    public static long parseCents(String amount) {
        if (amount == null) throw new IllegalArgumentException("INVALID AMOUNT");
        BigDecimal bd = new BigDecimal(amount.trim());
        if (bd.signum() <= 0) throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        return bd.movePointRight(2).longValueExact();
    }

    public static String format(long cents) {
        long whole = cents / 100;
        long frac = cents % 100;
        return String.format("%d.%02d", whole, frac);
    }
}

